#!/usr/bin/env python3
"""Count-only scan of this host's Claude Code transcripts for advisor iterations.

Populations: subagent transcripts (agent-*.jsonl below a "subagents" directory,
Agent-tool and workflow children; workflow journal.jsonl files are not agent
transcripts and are skipped) and main-session transcripts (<project>/<session>.jsonl).
Within each transcript, assistant rows are deduplicated by message.id, keeping the
row with the largest total of the four usage counters and skipping <synthetic> rows,
as transcriptUsage in examples/claude-native/workflows/child-usage.mjs does. Each
kept message's usage.iterations[] entries of type advisor_message are summed by
model. Prints counts only: no paths, identifiers or transcript content.
"""
import json
import os
import sys
from collections import Counter, defaultdict
from datetime import datetime, timezone

COUNTERS = ("input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens")
ROOT = os.path.expanduser("~/.claude/projects")


def total(usage):
    usage = usage if isinstance(usage, dict) else {}
    return sum(usage[k] for k in COUNTERS if isinstance(usage.get(k), int))


def populations():
    subagents, main = [], []
    for directory, _folders, names in os.walk(ROOT):
        parts = os.path.relpath(directory, ROOT).split(os.sep)
        for name in names:
            if not name.endswith(".jsonl"):
                continue
            if "subagents" in parts:
                if name.startswith("agent-"):
                    subagents.append(os.path.join(directory, name))
            elif len(parts) == 1 and parts[0] != ".":
                main.append(os.path.join(directory, name))
    return {"subagent_transcripts": sorted(subagents), "main_session_transcripts": sorted(main)}


def scan(files):
    out = Counter(transcripts=len(files), unparsed_lines=0, assistant_rows_without_message_id=0)
    by_model = defaultdict(Counter)
    for path in files:
        kept = {}
        with open(path, encoding="utf-8", errors="replace") as handle:
            for index, line in enumerate(handle):
                try:
                    row = json.loads(line)
                except ValueError:
                    out["unparsed_lines"] += 1
                    continue
                if not isinstance(row, dict) or row.get("type") != "assistant":
                    continue
                message = row.get("message")
                if not isinstance(message, dict) or message.get("model") == "<synthetic>":
                    continue
                key = message.get("id") or ("missing", index)
                if not message.get("id"):
                    out["assistant_rows_without_message_id"] += 1
                if key not in kept or total(message.get("usage")) >= total(kept[key].get("usage")):
                    kept[key] = message
        out["unique_assistant_messages"] += len(kept)
        with_advisor = False
        for message in kept.values():
            usage = message.get("usage") if isinstance(message.get("usage"), dict) else {}
            iterations = [item for item in (usage.get("iterations") or [])
                          if isinstance(item, dict) and item.get("type") == "advisor_message"]
            if not iterations:
                continue
            with_advisor = True
            out["messages_with_advisor_iterations"] += 1
            for item in iterations:
                counts = by_model[str(item.get("model") or "(unresolved)")]
                counts["advisor_iterations"] += 1
                for key in COUNTERS:
                    if isinstance(item.get(key), int):
                        counts[key] += item[key]
        out["transcripts_with_advisor_iterations"] += with_advisor
    out["advisor_iterations"] = sum(counts["advisor_iterations"] for counts in by_model.values())
    result = dict(sorted(out.items()))
    result["advisor_by_model"] = {model: dict(sorted(counts.items())) for model, counts in sorted(by_model.items())}
    return result


def main():
    scanned_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    report = {"scanned_at_utc": scanned_at,
              "populations": {name: scan(files) for name, files in populations().items()}}
    json.dump(report, sys.stdout, indent=2, sort_keys=True)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
